content.css:
.stf{background:var(--color-surface,#fafafa);border-top:1px solid var(--color-border,#e5e5e5);font-family:var(--font-sans,Inter,ui-sans-serif,system-ui,sans-serif);color:var(--color-text,#1a1a1a)}
.stf-inner{max-width:1180px;margin:0 auto;padding:4.5rem 1.5rem 2rem}
.stf-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1.2fr;gap:3rem;margin-bottom:3.5rem}
.stf-brand{max-width:22rem}
.stf-logo{display:inline-flex;align-items:center;gap:.55rem;font-family:var(--font-heading,inherit);font-size:1.0625rem;font-weight:700;letter-spacing:-.02em;color:var(--color-text,#1a1a1a);text-decoration:none}
.stf-mark{display:block;width:30px;height:30px}
.stf-tagline{margin:1rem 0 0;font-size:.9375rem;color:var(--color-text-secondary,#525252);line-height:1.7}
.stf-social{display:flex;gap:1rem;margin-top:1.25rem;font-size:.875rem}
.stf-social a{color:var(--color-muted,#8b8b8b);text-decoration:none}
.stf-social a:hover{color:var(--color-brand,#e2603a)}
.stf-heading,.stf .widget-title{font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.12em;color:var(--color-muted,#8b8b8b);margin:0 0 1.1rem}
.stf-links{display:flex;flex-direction:column;gap:.65rem}
.stf-links a{color:var(--color-text-secondary,#525252);text-decoration:none;font-size:.9375rem;transition:color 140ms ease}
.stf-links a:hover{color:var(--color-brand,#e2603a)}
.stf .widget-content p{color:var(--color-text-secondary,#525252);font-size:.9375rem;line-height:1.7;margin:0 0 .5rem}
.stf .widget-content a{color:var(--color-text-secondary,#525252)}
.stf-bottom{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:1rem;padding-top:1.75rem;border-top:1px solid var(--color-border,#e5e5e5)}
.stf-copy{font-size:.875rem;color:var(--color-muted,#8b8b8b);margin:0}
.stf-legal{display:flex;gap:1.25rem;font-size:.875rem}
.stf-legal a{color:var(--color-muted,#8b8b8b);text-decoration:none}
.stf-legal a:hover{color:var(--color-text,#1a1a1a)}
.stf .theme-switcher{display:flex;gap:.25rem;padding:.25rem;background:var(--color-bg,#fff);border:1px solid var(--color-border,#e5e5e5);border-radius:var(--radius,.5rem)}
.stf .theme-btn{display:flex;align-items:center;justify-content:center;width:30px;height:26px;background:transparent;border:none;color:var(--color-muted,#8b8b8b);border-radius:var(--radius,.5rem);cursor:pointer;transition:all 140ms ease}
.stf .theme-btn:hover{color:var(--color-text-secondary,#525252)}
.stf .theme-btn.active{background:var(--color-surface,#f7f7f7);color:var(--color-text,#1a1a1a)}
@media (max-width:940px){.stf-grid{grid-template-columns:1fr 1fr;gap:2.5rem}.stf-brand{grid-column:1 / -1}}
@media (max-width:560px){.stf-grid{grid-template-columns:1fr}.stf-bottom{flex-direction:column;align-items:flex-start}}
